#[derive(Debug, Clone)]
pub struct DraftArgs {
    pub client: String,
    pub engagement: String,
    pub number: ProposalNumber,
    pub overview: ProposalOverview,
    pub deliverables: Vec<Deliverable>,
    pub term: EngagementTerm,
    pub exclusions: Option<Vec<Exclusion>>,
    pub line_items: Vec<LineItem>,
    pub valid_for: Option<ValidityWindow>,
}

pub fn dispatch_draft(
    repo: &mut impl crate::kernel::Repository<Proposal>, route: Option<&crate::kernel::RoutingEnvelope>, args: DraftArgs, mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>, tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Proposal> {
        args.number.check_invariants()?;
        args.overview.check_invariants()?;
        for item in &args.deliverables { item.check_invariants()?; }
        args.term.check_invariants()?;
        if let Some(items) = &args.exclusions { for item in items { item.check_invariants()?; } }
        for item in &args.line_items { item.check_invariants()?; }
        if let Some(v) = &args.valid_for { v.check_invariants()?; }
    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, PROPOSAL_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
        Some(__route) => {
        __route.require_depth(0)?;
        crate::kernel::Hydrate::Act { id: __route.aggregate().to_string() }
    }
        None => { let __hydrate_id: String = args.number.value.to_string(); crate::kernel::Hydrate::Create {
        id: __hydrate_id,
        build: Box::new(|| Proposal {
            client: Some(args.client.clone()),
            engagement: Some(args.engagement.clone()),
            number: Some(args.number.clone()),
            overview: Some(args.overview.clone()),
            deliverables: args.deliverables.clone(),
            term: Some(args.term.clone()),
            exclusions: args.exclusions.clone(),
            line_items: args.line_items.clone(),
            valid_for: args.valid_for.clone(),
            revisions: vec![],
            status: "drafted".to_string(),
        }),
        state_independent: false,
    } }
    },
        "Draft",
        "EmbryonautFoundersApp::Proposal",
        "Proposal",
        "number.value",
        &with_references,
        &[

        ],
        None,
        |record| {
        record.number = Some(args.number.clone());
        record.overview = Some(args.overview.clone());
        record.deliverables = args.deliverables.clone();
        record.term = Some(args.term.clone());
        record.exclusions = args.exclusions.clone();
        record.line_items = args.line_items.clone();
        record.valid_for = args.valid_for.clone();
            Ok(())
        },
        &[

        ],
        &proposal_invariants(),
        &["ProposalDrafted"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

